mapper.select:
SELECT tr.orgId, tr.orgName, tr.treatDate, tr.patientId, tr.patientName, tr.mobile, tr.gender, tr.treatType, tr.regDentistId, tr.regDentistName, tr.appointTime, tr.appointDuration, tr.appointContent, tr.regTime, tr.treatStartTime, tr.treatEndTime, tr.treatWaitingTime, tr.treatExpendTime FROM ( SELECT btp.org_id AS orgId, bo.abbreviation AS orgName, DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) AS treatDate, btp.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, bp.gender AS gender, btp.treat_type AS treatType, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName, DATE_FORMAT( btp.appoint_start_time, '%H:%i' ) AS appointTime, btp.appoint_duration AS appointDuration, btp.appoint_content AS appointContent, DATE_FORMAT( btp.registered_time, '%H:%i' ) AS regTime, DATE_FORMAT( btp.treat_start_time, '%H:%i' ) AS treatStartTime, DATE_FORMAT( btp.treat_end_time, '%H:%i' ) AS treatEndTime, TIMESTAMPDIFF( MINUTE, btp.registered_time, DATE_FORMAT( btp.treat_start_time, '%H:%i' ) ) AS treatWaitingTime, TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time ) AS treatExpendTime FROM base_treatment_process btp LEFT JOIN base_organization bo ON btp.org_id = bo.org_id LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) tr
and tr.orgId = #{query.orgId}
and concat(ifnull(tr.patientName, ''), ifnull(tr.pinyinName, ''), ifnull(tr.mobile, '')) like concat('%', #{query.keyWord}, '%')
and tr.treatDate >= #{query.treatStartDate}
and tr.treatDate <= #{query.treatEndDate}
and tr.regDentistId in
#{item}
ORDER BY tr.treatDate DESC
